{
  "story": "Mitosis replicates a cell into two identical daughter nuclei through distinct chromosomal phases.",
  "aha": {
    "stateId": "anaphase",
    "observation": "Sister chromatids pull apart toward opposite poles."
  },
  "layout": {
    "preset": "stepper-card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "values": "variant.states.active"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "target": "variant.states.calloutRegion",
        "text": "variant.states.sentence",
        "values": "variant.states.why"
      }
    },
    {
      "id": "reads",
      "kind": "value-readout",
      "bind": {
        "values": "variant.states.readouts"
      }
    },
    {
      "id": "prog",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.stepIndex"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Mitosis Step",
      "options": [
        "prophase",
        "metaphase",
        "anaphase",
        "telophase"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Mitosis Cycle",
        "regions": [
          {
            "id": "nucleus",
            "label": "Nucleus",
            "phases": [
              "condensing",
              "aligned",
              "separating",
              "divided"
            ]
          }
        ],
        "states": [
          {
            "id": "prophase",
            "label": "Prophase",
            "short": "Condense",
            "sentence": "Chromatin condenses into visible chromosomes inside the nucleus.",
            "why": "DNA packs tightly for safe movement.",
            "active": ["nucleus"],
            "calloutRegion": "nucleus",
            "readouts": [
              {
                "id": "r1",
                "label": "Phase",
                "value": "1 of 4"
              }
            ]
          },
          {
            "id": "metaphase",
            "label": "Metaphase",
            "short": "Align",
            "sentence": "Chromosomes line up along the cell equator.",
            "why": "Ensures equal distribution.",
            "active": ["nucleus"],
            "calloutRegion": "nucleus",
            "readouts": [
              {
                "id": "r1",
                "label": "Phase",
                "value": "2 of 4"
              }
            ]
          },
          {
            "id": "anaphase",
            "label": "Anaphase",
            "short": "Pull",
            "sentence": "Sister chromatids pull apart toward opposite poles.",
            "why": "Separates duplicate DNA copies.",
            "active": ["nucleus"],
            "calloutRegion": "nucleus",
            "readouts": [
              {
                "id": "r1",
                "label": "Phase",
                "value": "3 of 4"
              }
            ]
          },
          {
            "id": "telophase",
            "label": "Telophase",
            "short": "Form",
            "sentence": "Two new nuclear envelopes form around the separated sets.",
            "why": "Completes nuclear division.",
            "active": ["nucleus"],
            "calloutRegion": "nucleus",
            "readouts": [
              {
                "id": "r1",
                "label": "Phase",
                "value": "4 of 4"
              }
            ]
          }
        ]
      }
    ]
  }
}
